CREATE TABLE article_exports(id text PRIMARY KEY,session_id text NOT NULL,request_id text NOT NULL REFERENCES generation_requests,article_id text NOT NULL REFERENCES articles,format text NOT NULL CHECK(format IN ('markdown','markdown_zip')),renderer_version integer NOT NULL DEFAULT 1,revision bigint NOT NULL DEFAULT 1,status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','running','retry_wait','ready','failed','expired','unavailable')),epoch bigint NOT NULL DEFAULT 0,attempts integer NOT NULL DEFAULT 0,active_ms bigint NOT NULL DEFAULT 0,lease_until timestamptz,deadline_at timestamptz NOT NULL DEFAULT now()+interval '10 minutes',storage_key text,bytes bigint,sha256 text,failure jsonb,retry_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),ready_at timestamptz,expires_at timestamptz,file_deleted boolean NOT NULL DEFAULT false);
CREATE INDEX exports_request ON article_exports(session_id,request_id,created_at DESC);
CREATE TABLE export_download_leases(id text PRIMARY KEY,export_id text NOT NULL REFERENCES article_exports,session_id text NOT NULL,expires_at timestamptz NOT NULL DEFAULT now()+interval '5 minutes');
